-- runtime-config.lua is generated by entrypoint.sh at container start
local config = dofile_once("mods/noita-docker-harness/runtime-config.lua") or {}

ModMagicNumbersFileAdd("mods/noita-docker-harness/magic-numbers.xml")

if config.seed then
  SetWorldSeed(config.seed)
end

function OnWorldPreUpdate()
  -- Z:\ is wine's mapping of the container filesystem root, so this writes
  -- /app/player_ready, which `just wait` polls via `docker exec`.
  local f, err = io.open([[Z:\app\player_ready]], "w")
  if not f then
    error("noita-docker-harness: could not write the ready signal: " .. tostring(err))
  end
  f:close()
  OnWorldPreUpdate = nil
end
